'QZ_Not_Running' => 'اس کمپیوٹر پر QZ Tray نہیں چل رہا۔ اسے qz.io سے انسٹال کریں اور چلتا رہنے دیں، پھر جب QZ پوچھے تو اس ویب سائٹ کو اجازت دیں۔',
'Detect_Printers' => 'پرنٹرز تلاش کریں',
'QZ_Download_Cert' => 'سرٹیفکیٹ ڈاؤن لوڈ کریں (override.crt)',
'QZ_Setup_Title' => 'QZ Tray پرنٹنگ کیسے سیٹ اپ کریں (ایک بار، لیبل پرنٹ کرنے والے ہر کمپیوٹر پر)',
'QZ_Step_Install' => '1. اس کمپیوٹر پر QZ Tray انسٹال کریں — اسے qz.io سے مفت ڈاؤن لوڈ کریں، پھر چلائیں اور چلتا رہنے دیں (یہ Windows پر سسٹم ٹرے یا macOS پر مینیو بار میں رہتا ہے)۔',
'QZ_Step_Connect' => '2. اپنا لیبل پرنٹر USB سے منسلک کریں اور چیک کریں کہ یہ آپریٹنگ سسٹم میں انسٹال ہے (Windows: Settings > Printers & scanners — macOS: System Settings > Printers & Scanners)۔',
'QZ_Step_Detect' => '3. اس کمپیوٹر کے پرنٹرز تلاش کرنے کے لیے اوپر "پرنٹر کا نام" کے ساتھ ⟳ بٹن پر کلک کریں، پھر اپنا لیبل پرنٹر منتخب کریں۔ کمپیوٹر کا ڈیفالٹ پرنٹر استعمال کرنے کے لیے فیلڈ خالی چھوڑیں۔',
'QZ_Step_Cert' => '4. اجازت کے پاپ اپ کے بغیر پرنٹنگ کے لیے نیچے سے سرٹیفکیٹ ڈاؤن لوڈ کریں اور اسے override.crt نام دے کر QZ Tray کے انسٹالیشن فولڈر میں کاپی کریں (Windows: C:\\Program Files\\QZ Tray — macOS: /Applications/QZ Tray.app/Contents/Resources — Linux: /opt/qz-tray)۔ پھر QZ Tray بند کر کے دوبارہ چلائیں۔',
'QZ_Step_Test' => '5. نیچے "ٹیسٹ لیبل پرنٹ کریں" پر کلک کریں۔ اگر QZ Tray اجازت مانگے تو Allow پر کلک کریں — سرٹیفکیٹ انسٹال ہونے پر یہ دوبارہ نہیں پوچھے گا۔',
'QZ_Step_Save' => '6. یہ ترتیبات محفوظ کرنے کے لیے جمع کرائیں پر کلک کریں۔ بارکوڈ پرنٹ صفحے کے لیبلز اب براؤزر پرنٹ ڈائیلاگ کے بغیر براہ راست اس پرنٹر پر پرنٹ ہوں گے۔',
'QZ_Setup_Note' => 'QZ Tray اس کمپیوٹر پر چلتا ہے جس سے آپ براؤز کر رہے ہیں، اس لیے یہ اس وقت بھی کام کرتا ہے جب Stocky ریموٹ سرور پر ہوسٹ ہو۔ لیبل پرنٹ کرنے والے ہر کمپیوٹر پر QZ Tray انسٹال ہونا ضروری ہے۔',
'PWA_Enabled' => 'قابل انسٹال ایپ فعال کریں',
