'Ord_Guide_Lifecycle_Confirmed' => 'آپ نے آرڈر قبول کر لیا۔ Stocky آپ کے منتخب گودام میں ایک فروخت بناتا ہے اور اسٹاک منہا کرتا ہے — وہی فروخت وہ ریکارڈ ہے جس سے آپ کی اسٹاک، ادائیگی اور منافع کی رپورٹس پڑھتی ہیں۔',
'Ord_Guide_Lifecycle_Shipped' => 'آپ نے آرڈر روانہ کر دیا۔ صرف تکمیل: اسٹاک تصدیق کرتے وقت ہی منہا ہو چکا تھا۔',
