'Ord_Guide_Payment_Paid' => 'گاہک پیمنٹ گیٹ وے کے ذریعے پہلے ہی آن لائن ادائیگی کر چکا ہے۔ آرڈر کی تصدیق سے فروخت ادا شدہ کے طور پر بنتی ہے اور ادائیگی آپ کے لیے درج ہو جاتی ہے — مزید کچھ کرنے کی ضرورت نہیں۔',
'Ord_Guide_Payment_Pending' => 'کیش آن ڈیلیوری، بینک ٹرانسفر یا بعد میں ادائیگی کا کوئی اور طریقہ۔ آرڈر کی تصدیق سے فروخت غیر ادا شدہ کے طور پر بنتی ہے، اس لیے رقم وصول کرنے کے بعد آپ اسے خود درج کرتے ہیں — نیچے دیے گئے مراحل دیکھیں۔',
'Ord_Guide_Payment_Failed' => 'گیٹ وے نے ادائیگی مسترد کر دی یا گاہک نے اسے ادھورا چھوڑ دیا۔ آرڈر خودکار طور پر منسوخ ہو جاتا ہے۔',
'Ord_Guide_MarkPaid_Title' => 'ادائیگی کو زیر التوا سے ادا شدہ میں تبدیل کرنا',
'Ord_Guide_MarkPaid_Step1' => 'پہلے یہاں آرڈر کی تصدیق کریں — تصدیق سے ہی فروخت بنتی ہے۔',
'Ord_Guide_MarkPaid_Step2' => 'فروخت > تمام فروخت کھولیں اور وہ فروخت تلاش کریں (وہی گاہک، اور تفصیلات کے صفحے پر وہ آن لائن آرڈر دکھایا جاتا ہے جس سے یہ بنی)۔',
'Ord_Guide_MarkPaid_Step3' => 'قطار کا ایکشن مینیو کھولیں اور ادائیگی بنائیں منتخب کریں۔',
'Ord_Guide_MarkPaid_Step4' => 'رقم، ادائیگی کا طریقہ اور تاریخ درج کریں، پھر محفوظ کریں۔ رقم کے مطابق فروخت خود بخود جزوی یا ادا شدہ میں چلی جاتی ہے۔',
'Ord_Guide_MarkPaid_Note' => 'یہاں دکھائی گئی ادائیگی کی حالت چیک آؤٹ کا انتخاب درج کرتی رہتی ہے اور ویسے ہی رہتی ہے۔ فروخت اکاؤنٹنگ ریکارڈ ہے، اور وہی آپ کی ادائیگی اور منافع کی رپورٹس کو ڈیٹا دیتی ہے۔ جو آپ نے درج کیا اس کا جائزہ لینے یا ترمیم کرنے کے لیے فروخت پر ادائیگیاں دکھائیں استعمال کریں۔',
'Ord_Guide_Notes_Title' => 'جاننا مفید ہے',
'Ord_Guide_Note_Warehouse' => 'تصدیق کرتے وقت آپ جو گودام منتخب کرتے ہیں وہی طے کرتا ہے کہ اسٹاک کہاں سے لیا جائے۔ جو گودام پورا آرڈر پورا نہیں کر سکتے انہیں اس فہرست میں اسٹاک ختم کے طور پر نشان زد کیا جاتا ہے۔',
'Ord_Guide_Note_Preorder' => 'پری آرڈر آئٹمز اسٹاک کی جانچ سے مستثنیٰ ہیں، اس لیے ان پر مشتمل آرڈر کی تصدیق مقدار موجود نہ ہونے پر بھی ہو سکتی ہے۔',
