'Upd_Guide_Wrong_Unreachable' => '{label} — {path} پر علیحدہ {console} استعمال کریں۔ یہ تب بھی کام کرتا ہے جب سائٹ مینٹیننس موڈ میں ہو یا ایڈمن پینل اثاثے خراب ہوں، اور وہی جاری رکھیں / رول بیک کارروائیاں پیش کرتا ہے۔ مینٹیننس اسکرین کے نیچے ایک غیر نمایاں "ایڈمنسٹریٹر رسائی" لنک بھی ہے۔',
