'Upd_Guide_Backups_Created' => 'ہر اپ ڈیٹ کسی بھی چیز کو چھونے سے {before} ایک بیک اپ بناتی ہے: اپ ڈیٹ سے تبدیل ہو سکنے والی تمام ایپلیکیشن فائلیں، {env} کی کاپی، اور مکمل ڈیٹا بیس ڈمپ۔ اپ لوڈز اور {storage} کو اپ ڈیٹ کبھی تبدیل نہیں کرتی اس لیے وہ اس کا حصہ نہیں — ان کے اپنے بیک اپس رکھیں۔ بیک اپس {path} میں رہتے ہیں اور ویب سے کبھی قابل رسائی نہیں ہوتے۔',
'Upd_Before' => 'پہلے',
