'Woo_Guide_Instant_Note' => 'صرف وہ پروڈکٹس پش ہوتی ہیں جو پہلے سے WooCommerce سے منسلک ہیں — جو کبھی سنک نہیں ہوئی اس کے لیے شاپ میں درست کرنے کو کچھ نہیں۔ ویری ایبل پروڈکٹس اپنے پیرنٹ کے ذریعے جاتی ہیں، اور کومبو تب دوبارہ پش ہوتا ہے جب اس کا کوئی جزو حرکت کرے۔ بلک آپریشنز (پروڈکٹ حذف کرنا، گودام ری سیٹ کرنا) ایونٹ چلائے بغیر اسٹاک لکھتے ہیں، جو گھنٹہ وار اسٹاک سنک بھی رکھنے کی ایک وجہ ہے۔',
