'Woo_After' => 'بعد',
'Woo_Guide_Shop_Stops_Answering' => 'جواب دینا بند کرنے والی شاپ کو آٹھ سیکنڈ بعد چھوڑ دیا جاتا ہے، اور پشز پانچ منٹ کے لیے رک جاتے ہیں تاکہ ہر سیل دوبارہ اس کا انتظار نہ کرے؛ اس دوران آنے والی تبدیلیاں وقفے کے بعد پہلے پش کے ساتھ جاتی ہیں، اور گھنٹہ وار اسٹاک سنک بہرحال کمی پوری کر دیتا ہے۔ ہر وقفہ لاگز ٹیب میں درج ہوتا ہے۔',
