'Woo_On_A_Schedule' => 'شیڈول پر',
'Woo_Guide_Scheduled_Lead' => 'ہر چیز وقتاً فوقتاً دونوں طرف دوبارہ جانچی جاتی ہے۔ اسی طرح آرڈرز ERP تک پہنچتے ہیں، کیٹلاگ شائع ہوتا ہے، اور تیز راستے سے چھوٹ جانے والی چیزیں درست ہوتی ہیں۔ ہر جاب کا اپنا cron اندراج ہوتا ہے، اس لیے آپ صرف وہی چلاتے ہیں جو چاہتے ہیں۔',
