'Woo_Or_No_Cron' => 'یا بالکل cron کے بغیر',
'Woo_Guide_No_Cron_Text' => 'یہاں ہر ٹیب مانگ پر سنک کرتا ہے، اور دستی سنک صفحہ کھلا رہنے تک اپنے بیچز خود خالی کرتا ہے — اس لیے چھوٹی شاپ بغیر کسی cron اندراج کے چل سکتی ہے۔ نقصان یہ ہے کہ جب کوئی نہیں دیکھ رہا ہوتا تب کچھ نہیں ہوتا: آرڈرز تبھی آتے ہیں جب کوئی بٹن دبائے۔',
