'Shopify_G_Lead_Generic' => 'Shopify شاپ ERP کے ساتھ کیسے ہم آہنگ رہتی ہے۔ اس کی اپنی حالت دیکھنے کے لیے اوپر اسٹور منتخب کریں، یا اسے جوں کا توں پڑھیں — cron لائن اور webhook URL ہر منسلک اسٹور کے لیے ایک جیسے ہیں۔',
'Shopify_G_Ways_Note' => 'زیادہ تر شاپس دونوں چلاتی ہیں: پہلا شاپ کو منٹ بہ منٹ تازہ رکھتا ہے، دوسرا وہ سب پکڑتا ہے جو پہلے سے چھوٹ گیا — ایسا webhook جو کبھی نہیں پہنچا، Shopify ایڈمن میں براہ راست کی گئی ترمیم، ایسی رات جب سائٹ بند تھی۔',
