'Shopify_G_Credentials' => 'Shopify اسناد',
'Shopify_G_Cred_Intro' => 'جنوری 2026 سے Shopify ایڈمن کے اندر کسٹم ایپس نہیں بناتا، اس لیے کنکشن کی دو قسمیں ہیں:',
'Shopify_G_Cred_DevDash' => '{app} (اب منسلک کوئی بھی شاپ) — {path}۔ یہ اسٹور جو سنک کرتا ہے اس کے لیے Admin API scopes دیں، ایپ کو شاپ پر انسٹال کریں، پھر ایپ کے Settings صفحے سے {clientId} اور {clientSecret} کو {where} میں کاپی کریں۔ ERP انہیں خود ایکسیس ٹوکن سے بدلتا ہے اور ہر 24 گھنٹے میں ختم ہونے سے پہلے اسے تجدید کرتا ہے۔ client secret webhooks پر بھی دستخط کرتا ہے، اس لیے کچھ اور درکار نہیں۔ ایپ اور شاپ ایک ہی Shopify تنظیم میں ہونی چاہئیں۔',
'Shopify_G_Dev_Dashboard_App' => 'Dev Dashboard ایپ',
'Shopify_G_Cred_Legacy' => '{app} (2026 سے پہلے ایڈمن میں بنائی گئی) — اپنے {token} ({prefix}) اور webhook دستخطی سیکرٹ کے طور پر اپنی {secret} کے ساتھ بغیر تبدیلی کام کرتی رہتی ہے۔ یہ ٹوکن والی قدر نہیں ہے، اور انہیں الٹا لگانا webhooks مسترد ہونے کی عام وجہ ہے۔',
