'Shopify_G_Manual_Desc' => '{centre} سے شروع کیا گیا سنک فوراً جواب دیتا ہے اور پس منظر میں چھوٹے حصوں میں چلتا ہے، ہر ایک پچھلے کے رکنے کی جگہ سے جاری رہتا ہے۔ بڑا کیٹلاگ کبھی ایسی ہوسٹنگ سے بیچ میں نہیں کٹتا جو لمبی ویب درخواستیں ختم کر دیتی ہے (LiteSpeed، nginx، لوڈ بیلنسر)، اور صفحہ بند کرنے سے یہ نہیں رکتا۔ اس کا ورکر ایک اور cron لائن ہے:',
'Shopify_G_Cron_Copied' => 'Cron لائن کاپی ہو گئی',
'Shopify_G_Manual_Note' => 'اس کے بغیر بھی سنک مکمل ہوتا ہے، لیکن صرف تب تک جب تک Sync Centre صفحہ کھلا رہے: جب کوئی ورکر چند سیکنڈ میں رن نہ اٹھائے تو صفحہ خود ایک ایک مختصر درخواست کر کے اسے جاری رکھتا ہے۔ Windows پر ہر منٹ Task Scheduler استعمال کریں: پروگرام {program}، آرگیومنٹس {args}، {dir} میں شروع کیا گیا۔',
