'Shopify_G_Webhooks_Desc' => 'آرڈرز، آرڈر کی حیثیت میں تبدیلیاں، اور Shopify میں کی گئی پروڈکٹ، صارف اور اسٹاک ترامیم۔ اسٹور کھولیں اور اس کے {tab} پر {button} دبائیں — دو بار دبانا محفوظ ہے۔ Shopify یہاں بھیجتا ہے:',
'Shopify_G_Webhooks_Tab' => 'Webhooks ٹیب',
'Shopify_G_Webhooks_Note' => 'پتہ انٹرنیٹ سے HTTPS پر قابل رسائی ہونا چاہیے — Shopify {localhost} یا {test} ڈومین پر نہیں بھیجے گا۔ ہر ڈیلیوری ایک بار درج ہوتی ہے، اس لیے Shopify کی دوبارہ کوششیں ڈپلیکیٹ آرڈر نہیں بنا سکتیں، اور ناکام کو دوبارہ چلایا جا سکتا ہے۔ مرحلہ 1 کا دستخطی سیکرٹ محفوظ ہونے تک ڈیلیوریز مسترد ہوتی ہیں۔',
'Shopify_G_Instant_Out' => 'فوری اسٹاک پش — ERP → شاپ',
'Shopify_G_Setting_Missed' => 'یہ وہ سیٹنگ ہے جو لوگ نظر انداز کر دیتے ہیں',
'Shopify_G_Pos_Not_Auto' => 'POS سیل خود بخود Shopify تک {not} پہنچتی۔ بند رہنے پر شاپ کو اگلے انوینٹری پش مرحلے پر ہی پتہ چلتا ہے — اور اس دوران وہ ایسا یونٹ فروخت کر سکتی ہے جو آپ کاؤنٹر پر پہلے ہی بیچ چکے ہیں۔',
'Shopify_G_Not' => 'نہیں',
'Shopify_G_Tick_Push' => '{where} پر {setting} ٹک کریں۔ بس یہی سارا سیٹ اپ ہے — نہ ورکر، نہ cron۔ پھر ہر سیل، واپسی اور ایڈجسٹمنٹ فروخت محفوظ ہوتے ہی صرف انہی پروڈکٹس کا پش بھیجتی ہے، اور بیس لائنوں کی سیل پر ایک پش لگتا ہے، بیس نہیں۔ کاؤنٹر کبھی اس کا انتظار نہیں کرتا۔',
'Shopify_G_This_Store' => 'یہ اسٹور:',
