'Shopify_G_Push_Off' => 'آف — اسٹاک صرف شیڈول پر',
'Shopify_G_Push_Note' => 'صرف وہ پروڈکٹس جن کی پہلے سے Shopify میپنگ ہے، اور صرف اس اسٹور کے گودام میں حرکات، پش ہوتی ہیں۔ بلک آپریشنز — پروڈکٹ حذف کرنا، گودام ری سیٹ کرنا — ایونٹ چلائے بغیر اسٹاک لکھتے ہیں، جو شیڈول شدہ انوینٹری مرحلہ بھی رکھنے کی ایک وجہ ہے۔',
'Shopify_G_Nothing_Install' => 'کچھ اور انسٹال کرنے کی ضرورت نہیں',
'Shopify_G_No_Worker_Note' => 'کسی بھی حصے کو کیو ورکر یا cron اندراج کی ضرورت نہیں۔ آنے والا webhook Shopify کی درخواست میں ہی سنبھالا جاتا ہے؛ باہر جانے والا اسٹاک پش اسی پروسیس میں چلتا ہے جس نے سیل سنبھالی، جواب واپس جانے کے {after} — اس لیے کاؤنٹر کبھی Shopify کا انتظار نہیں کرتا، اور جواب دینا بند کرنے والی شاپ کو دس سیکنڈ بعد چھوڑ کر اگلے شیڈول انوینٹری پش پر چھوڑ دیا جاتا ہے۔',
'Shopify_G_After' => 'بعد',
'Shopify_G_Artisan_Note' => 'ایک استثناء: artisan کمانڈ سے ہونے والی اسٹاک تبدیلی کا کوئی جواب نہیں ہوتا جس کے بعد یہ چلے، اس لیے یہ {queue} پر قطار میں رکھی جاتی ہے۔ اگر آپ انہیں بھی فوری بھیجنا چاہتے ہیں تو وہ قطار خالی کریں:',
'Shopify_G_On_Schedule' => 'شیڈول پر',
'Shopify_G_On_Lower' => 'آن',
'Shopify_G_Off_Lower' => 'آف',
'Shopify_G_Scheduled_Lead' => 'ہر چیز وقتاً فوقتاً دونوں طرف دوبارہ جانچی جاتی ہے۔ حقیقی وقت سے سست، لیکن یہی فوری پش استعمال نہ کرنے والی شاپس پر اسٹاک باہر بھیجتا ہے، چھوٹا ہوا webhook پکڑتا ہے، اور پورا کیٹلاگ منتقل کرنے کا واحد طریقہ ہے۔',
'Shopify_G_Cron_Entry' => 'cron اندراج',
'Shopify_G_Cron_Entry_Desc' => 'اس کے بغیر کچھ شیڈول شدہ نہیں چلتا۔ ایک لائن، صرف اس ماڈیول کے لیے — اسے ان کے ساتھ شامل کریں جو آپ نے شیڈول کرنے کے لیے منتخب کیے ہیں:',
'Shopify_G_Cron_Note' => 'ہر پانچ منٹ سب سے باریک حد ہے جو منصوبہ استعمال کر سکتا ہے، کیونکہ پانچ منٹ سب سے کم مرحلہ وقفہ ہے۔ زیادہ وقفے والا اندراج بس کم از کم حد بن جاتا ہے — {example} کے ساتھ، 5 منٹ پر مقرر مرحلہ ہر 15 منٹ چلتا ہے۔ Windows پر Task Scheduler استعمال کریں: پروگرام {program}، آرگیومنٹس {args}، {dir} میں شروع کیا گیا۔',
'Shopify_G_Switch_On_Plan' => 'اسے آن کریں، اور منصوبہ منتخب کریں',
'Shopify_G_Plan_Desc' => '{where} سوئچ طے کرتا ہے کہ cron کچھ کر سکتا ہے یا نہیں؛ منصوبہ طے کرتا ہے کہ کیا کرتا ہے۔ ایک {step} ایک سمت میں ایک اینٹیٹی ہے جس کا اپنا وقفہ ہے — {first}، {second}۔ ڈیفالٹ وقفہ ہر اس مرحلے کے لیے استعمال ہوتا ہے جو اپنا باکس خالی چھوڑے۔',
'Shopify_G_Step_Lower' => 'مرحلہ',
'Shopify_G_Plan_Note' => 'منصوبہ خالی چھوڑیں تو اسٹور ڈیفالٹ وقفے پر آرڈرز پل اور اسٹاک پش کرتا ہے، جو زیادہ تر شاپس چاہتی ہیں۔ آرڈرز صرف پل ہوتے ہیں: صارف آرڈر Shopify پر دیتا ہے۔',
'Shopify_G_Schedule_On' => 'شیڈول آن',
